#!/usr/bin/env python3
"""Round 27: compile exact production verifier and compare with immutable pre-round27 functions."""
from pathlib import Path
import subprocess
import tempfile

source=Path("src/cryptanalysis/prime_root_trace.rs").read_text()
production=source[source.index("fn vmul("):source.index("\nfn canonical(")]
frozen="fn old_vproduct(a: &[u64], b: &[u64], p: u64) -> Vec<u64> {\n    if a.is_empty() || b.is_empty() {\n        return vec![];\n    }\n    let mut r = vec![0; a.len() + b.len() - 1];\n    for (i, &x) in a.iter().enumerate() {\n        // Sparse root polynomials often have zero middle coefficients.\n        // Multiplying those coefficients cannot change the accumulator.\n        if x == 0 { continue; }\n        for (j, &y) in b.iter().enumerate() {\n            if y == 0 { continue; }\n            // Fused multiply-accumulate: no u128 division for canonical\n            // small fields or the 61-bit Mersenne prime.\n            r[i + j] = if p == MAX_PRIME {\n                let product = x as u128 * y as u128;\n                let folded = ((product as u64) & MAX_PRIME)\n                    + (product >> 61) as u64 + r[i + j];\n                let folded = (folded & MAX_PRIME) + (folded >> 61);\n                if folded >= p { folded - p } else { folded }\n            } else if p <= u32::MAX as u64 {\n                // (p-1)^2 + (p-1) < 2^64 when p <= 2^32-1.\n                (r[i + j] + x * y) % p\n            } else {\n                ((r[i + j] as u128 + x as u128 * y as u128) % p as u128) as u64\n            };\n        }\n    }\n    trim(r)\n}\n\nfn old_vsquare(a: &[u64], p: u64) -> Vec<u64> {\n    // The general fused product wins for short 32-bit-field inputs in\n    // actual Rust benchmarks; use symmetric squaring for larger polynomials,\n    // and for 61-bit arithmetic where its crossover occurs earlier.\n    if a.len() <= 2 || (a.len() <= 4 && p <= u32::MAX as u64) {\n        return old_vproduct(a, a, p);\n    }\n    let mut result = vec![0; 2 * a.len() - 1];\n    for (i, &x) in a.iter().enumerate() {\n        let diagonal = vmul(x, x, p);\n        let sum = result[2 * i] + diagonal;\n        result[2 * i] = if sum >= p { sum - p } else { sum };\n        for (j, &y) in a.iter().enumerate().skip(i + 1) {\n            let cross = vmul(x, y, p);\n            let twice = cross + cross;\n            let twice = if twice >= p { twice - p } else { twice };\n            let sum = result[i + j] + twice;\n            result[i + j] = if sum >= p { sum - p } else { sum };\n        }\n    }\n    trim(result)\n}\n\nfn old_vdiv(a: &[u64], b: &[u64], p: u64) -> Result<(Vec<u64>, Vec<u64>), String> {\n    if b.is_empty() {\n        return Err(\"division by zero polynomial\".into());\n    }\n    // Degree-short dividends need neither a quotient allocation nor a\n    // costly field inversion. The input is already canonical here.\n    if a.len() < b.len() {\n        return Ok((vec![], a.to_vec()));\n    }\n    // A monic constant divisor leaves the dividend unchanged. Preserve\n    // canonical quotient trimming even if a standalone caller supplies\n    // trailing zero coefficients.\n    if b.len() == 1 && b[0] == 1 {\n        return Ok((trim(a.to_vec()), vec![]));\n    }\n    // Synthetic division by x + c needs only one running remainder and\n    // one quotient allocation, rather than a mutable dividend and a\n    // trim pass on every quotient digit.\n    if b.len() == 2 && b[1] == 1 {\n        let mut q = vec![0; a.len() - 1];\n        let mut carry = *a.last().unwrap();\n        for i in (1..a.len()).rev() {\n            q[i - 1] = carry;\n            let product = vmul(carry, b[0], p);\n            let value = a[i - 1];\n            carry = if value >= product { value - product }\n                    else { value + p - product };\n        }\n        return Ok((trim(q), if carry == 0 { vec![] } else { vec![carry] }));\n    }\n    let mut r = a.to_vec();\n    let mut q = vec![0; a.len() - b.len() + 1];\n    // GCD factors, X^p mod f divisors and root certificates are commonly\n    // monic. Avoid a full exponentiation to invert their leading 1.\n    let lead = *b.last().unwrap();\n    if lead == 1 {\n        // Synthetic division by a monic polynomial. The leading term\n        // cancels exactly, so neither its multiplication nor subtraction\n        // needs to be performed.\n        while !r.is_empty() && r.len() >= b.len() {\n            let shift = r.len() - b.len();\n            let c = *r.last().unwrap();\n            q[shift] = c;\n            r.pop();\n            for (i, &x) in b[..b.len() - 1].iter().enumerate() {\n                let product = vmul(c, x, p);\n                let old = r[shift + i];\n                r[shift + i] = if old >= product { old - product }\n                               else { old + p - product };\n            }\n            r = trim(r);\n        }\n    } else {\n        // Preserve the nonmonic route, including its original reduction\n        // order, rather than adding a branch to each inner iteration.\n        let inv = vpow(lead, p - 2, p);\n        while !r.is_empty() && r.len() >= b.len() {\n            let shift = r.len() - b.len();\n            let c = vmul(*r.last().unwrap(), inv, p);\n            q[shift] = c;\n            // c*lead cancels the top term exactly, even for nonmonic b.\n            r.pop();\n            for (i, &x) in b[..b.len() - 1].iter().enumerate() {\n                let product = vmul(c, x, p);\n                let old = r[shift + i];\n                r[shift + i] = if old >= product { old - product }\n                               else { old + p - product };\n            }\n            r = trim(r);\n        }\n    }\n    Ok((trim(q), r))\n}\n"
checks="\nfn next(s: &mut u64) -> u64 {\n    *s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);\n    *s ^ (*s >> 29)\n}\nfn fixture(p: u64, kind: usize) -> Vec<(Vec<u64>,Vec<u64>)> {\n    let mut seed = 0x2026_1119_0027u64 + kind as u64;\n    let mut out = Vec::new();\n    for _ in 0..128 {\n        let mut a=(0..15).map(|_| next(&mut seed)%p).collect::<Vec<u64>>();\n        let mut b=(0..8).map(|_| next(&mut seed)%p).collect::<Vec<u64>>();\n        a[14]=1;\n        match kind {\n            0 => b=vec![1],\n            1 => b=vec![0,1],\n            2 => b=vec![0,0,0,0,1],\n            3 => {b[0]=1;b[7]=1},\n            4 => {a.fill(0);a[0]=1},\n            5 => {a.fill(0);a[0]=1;a[14]=2},\n            6 => {a[0]=1;a[1]=1;a[2]=1},\n            7 => b=vec![0,1],\n            8 => b=vec![0,0,1],\n            9 => b=vec![0,0,0,0,1],\n            10=>{b=vec![1,2,3,1]},\n            _ => unreachable!(),\n        }\n        out.push((a,b));\n    }\n    out\n}\n#[test]\nfn round27_monomial_and_sparse_square_exact() {\n    let mut checks=0usize;\n    for p in [3u64,5,487,17497,1000000007,4294967291,MAX_PRIME] {\n        for kind in 0..11 {\n            for (a,b) in fixture(p,kind) {\n                for n in 0..=a.len() {\n                    let x=&a[..n];\n                    match kind {\n                        0..=3 => {\n                            assert_eq!(vproduct(x,&b,p),old_vproduct(x,&b,p),\"product p={p} kind={kind} n={n}\");\n                            assert_eq!(vproduct(&b,x,p),old_vproduct(&b,x,p),\"product reversed p={p} kind={kind} n={n}\");\n                            checks+=2;\n                        },\n                        4..=6 => {\n                            assert_eq!(vsquare(x,p),old_vsquare(x,p),\"square p={p} kind={kind} n={n}\");\n                            checks+=1;\n                        },\n                        _ => {\n                            assert_eq!(vdiv(x,&b,p),old_vdiv(x,&b,p),\"division p={p} kind={kind} n={n}\");\n                            checks+=1;\n                        },\n                    }\n                }\n            }\n        }\n    }\n    println!(\"round27 actual production Rust checks={checks}\");\n}\n#[test]\n#[ignore=\"actual production Rust paired benchmark\"]\nfn bench_round27_verifier_actual_rust() {\n    use std::hint::black_box;\n    use std::time::Instant;\n    fn sample(p:u64,kind:usize,data:&[(Vec<u64>,Vec<u64>)],fast:bool)->f64 {\n        let reps=if kind>=7 {40} else if kind>=4 {70} else {80};\n        let mut checksum=0u64;\n        let start=Instant::now();\n        for _ in 0..reps {\n            for (a,b) in data {\n                let (a,b,p)=(black_box(a),black_box(b),black_box(p));\n                let v=match kind {\n                    0..=3 => {let r=if fast {vproduct(a,b,p)}else{old_vproduct(a,b,p)};r.len() as u64+r.last().copied().unwrap_or(0)},\n                    4..=6 => {let r=if fast {vsquare(a,p)}else{old_vsquare(a,p)};r.len() as u64+r.last().copied().unwrap_or(0)},\n                    _=>{let (q,r)=if fast{vdiv(a,b,p).unwrap()}else{old_vdiv(a,b,p).unwrap()};\n                        q.len() as u64+r.len() as u64+q.last().copied().unwrap_or(0)},\n                };\n                checksum=checksum.wrapping_add(black_box(v));\n            }\n        }\n        black_box(checksum);\n        start.elapsed().as_nanos() as f64/(reps*data.len()) as f64\n    }\n    let names=[\"product_one\",\"product_x\",\"product_x4\",\"product_dense_control\",\n        \"square_one_term\",\"square_two_terms\",\"square_dense_control\",\n        \"division_x\",\"division_x2\",\"division_x4\",\"division_dense_control\"];\n    for p in [1000000007u64,MAX_PRIME] {\n        for kind in 0..names.len() {\n            let data=fixture(p,kind);\n            let (mut before,mut after)=(Vec::new(),Vec::new());\n            for t in 0..13 {\n                if t%2==0 {\n                    before.push(sample(p,kind,&data,false));\n                    after.push(sample(p,kind,&data,true));\n                } else {\n                    after.push(sample(p,kind,&data,true));\n                    before.push(sample(p,kind,&data,false));\n                }\n            }\n            before.sort_by(f64::total_cmp);after.sort_by(f64::total_cmp);\n            println!(\"round27 actual RUST p={p} {} {:.3} -> {:.3} ns ({:.3}x)\",names[kind],before[6],after[6],before[6]/after[6]);\n        }\n    }\n}\n"
rust = """
const MAX_PRIME:u64=(1u64<<61)-1;
fn trim(mut v:Vec<u64>)->Vec<u64>{while v.last()==Some(&0){v.pop();}v}
""" + production + "\n" + frozen + checks
with tempfile.TemporaryDirectory() as temp:
    src=Path(temp)/"round27_verifier.rs"
    exe=Path(temp)/"round27_verifier"
    src.write_text(rust)
    subprocess.run(["rustc","--edition=2021","-O","--test",str(src),"-o",str(exe)],check=True)
    subprocess.run([str(exe),"round27_monomial_and_sparse_square_exact","--nocapture"],check=True)
    subprocess.run([str(exe),"bench_round27_verifier_actual_rust","--ignored","--nocapture"],check=True)
